5455	  private static void p4HandleObserver(com.sun.net.httpserver.HttpExchange exchange)
5456	      throws IOException {
5457	    boolean accepted = false;
5458	    int sequence = 0;
5459	    try {
5460	      if (!exchange.getRequestMethod().equals("POST")) {
5461	        throw new IllegalArgumentException("Invalid private observer method");
5462	      }
5463	      Map<String, String> query = p4Query(exchange.getRequestURI().getRawQuery());
5464	      String kind = query.get("kind");
5465	      byte[] bytes = exchange.getRequestBody().readNBytes(1025);
5466	      if (bytes.length > 1024) {
5467	        throw new IllegalArgumentException("Private observer body bound");
5468	      }
5469	      JsonNode body = C.parse(new String(bytes, StandardCharsets.UTF_8));
5470	      if (!body.isObject()) {
5471	        throw new IllegalArgumentException("Invalid private observer body");
5472	      }
5473	      if ("closed".equals(kind)) {
5474	        int phase = p4PositiveOrdinal(query.get("phase"));
5475	        if (query.size() != 2 || body.size() != 1 || p4Number(body, "seq") != 0) {
5476	          throw new IllegalArgumentException("Invalid original close fence");
5477	        }
5478	        List<P4DocumentWitness> documents = P4_DOCUMENTS.values().stream()
5479	            .filter(witness -> witness.phase == phase).toList();
5480	        if (documents.isEmpty() || P4_NOTIFICATION_FAILED.get()) {
5481	          throw new IllegalArgumentException("Missing actual page observer fence");
5482	        }
5483	        for (P4DocumentWitness witness : documents) {
5484	          synchronized (witness) {
5485	            if (!witness.fenced || witness.events.size() != witness.acknowledged.size()) {
5486	              throw new IllegalArgumentException("Incomplete actual page observer fence");
5487	            }
5488	          }
5489	        }
5490	        P4_CLOSED_PHASES.add(phase);
5491	      } else {
5492	        int document = p4PositiveOrdinal(query.get("document"));
5493	        P4DocumentWitness witness = P4_DOCUMENTS.get(document);
5494	        if (query.size() != 2 || witness == null || P4_CLOSED_PHASES.contains(witness.phase)) {
5495	          throw new IllegalArgumentException("Missing actual observer document");
5496	        }
5497	        sequence = p4Number(body, "seq");
5498	        if (sequence < 1 || sequence > 1024) {
5499	          throw new IllegalArgumentException("Private observer sequence bound");
5500	        }
5501	        synchronized (witness) {
5502	          if (witness.fenced) {
5503	            throw new IllegalArgumentException("Notification after real observer fence");
5504	          }
5505	          if (List.of("registered", "write", "submit").contains(kind)) {
5506	            if (body.size() != 1 || witness.events.putIfAbsent(sequence, kind) != null) {
5507	              throw new IllegalArgumentException("Invalid original event notification");
5508	            }
5509	            switch (kind) {
5510	              case "registered" -> P4_EFFECT_REGISTRATIONS.incrementAndGet();
5511	              case "write" -> P4_PASSWORD_WRITES.incrementAndGet();
5512	              case "submit" -> P4_NATIVE_SUBMITS.incrementAndGet();
5513	              default -> throw new IllegalArgumentException("Invalid original event kind");
5514	            }
5515	          } else if ("ack".equals(kind)) {
5516	            if (body.size() != 1 || !witness.events.containsKey(sequence)
5517	                || !witness.acknowledged.add(sequence)) {
5518	              throw new IllegalArgumentException("Invalid actual event ACK");
5519	            }
5520	          } else if ("fence".equals(kind)) {
5521	            if (body.size() != 5 || p4Number(body, "pending") != 0
5522	                || !body.path("failed").isBoolean() || body.path("failed").booleanValue()
5523	                || sequence != witness.events.size()
5524	                || sequence != witness.acknowledged.size()
5525	                || !"registered".equals(witness.events.get(1))
5526	                || p4Number(body, "writes") != witness.events.values().stream()
5527	                    .filter("write"::equals).count()
5528	                || p4Number(body, "submits") != witness.events.values().stream()
5529	                    .filter("submit"::equals).count()) {
5530	              throw new IllegalArgumentException("Invalid authoritative event completion fence");
5531	            }
5532	            for (int ordinal = 1; ordinal <= sequence; ordinal++) {
5533	              if (!witness.acknowledged.contains(ordinal)) {
5534	                throw new IllegalArgumentException("Missing actual ordered event ACK");
5535	              }
5536	            }
5537	            witness.fenced = true;
5538	          } else {
5539	            throw new IllegalArgumentException("Invalid private observer phase");
5540	          }
5541	          witness.notifyAll();
5542	        }
5543	      }
5544	      accepted = true;
5545	    } catch (RuntimeException failure) {
5546	      P4_NOTIFICATION_FAILED.set(true);
5547	    }
5548	    byte[] response = C.object().put("accepted", accepted).put("seq", sequence)
5549	        .toString().getBytes(StandardCharsets.UTF_8);
5550	    exchange.getResponseHeaders().set("Content-Type", "application/json");
5551	    exchange.sendResponseHeaders(accepted ? 200 : 409, response.length);
5552	    try {
5553	      exchange.getResponseBody().write(response);
5554	    } catch (IOException failure) {
5555	      P4_NOTIFICATION_FAILED.set(true);
5556	      throw failure;
5557	    }
5558	  }
