5560	  private static void p4AwaitNativeSubmitFence(String query) {
5561	    try {
5562	      List<P4DocumentWitness> documents = P4_DOCUMENTS.values().stream()
5563	          .filter(witness -> witness.phase == P4_PHASE_ORDINAL.get()).toList();
5564	      if (query != null || documents.size() != 1) {
5565	        throw new IllegalArgumentException("Missing unique actual native submit document");
5566	      }
5567	      P4DocumentWitness witness = documents.getFirst();
5568	      long deadline = System.nanoTime() + Duration.ofMillis(2500).toNanos();
5569	      synchronized (witness) {
5570	        while (!witness.fenced && !P4_NOTIFICATION_FAILED.get() && System.nanoTime() < deadline) {
5571	          long remaining = deadline - System.nanoTime();
5572	          if (remaining <= 0) {
5573	            break;
5574	          }
5575	          java.util.concurrent.TimeUnit.NANOSECONDS.timedWait(witness, remaining);
5576	        }
5577	        if (!witness.fenced || !witness.events.containsValue("submit")
5578	            || witness.events.size() != witness.acknowledged.size()) {
5579	          P4_NOTIFICATION_FAILED.set(true);
5580	        }
5581	      }
5582	    } catch (RuntimeException failure) {
5583	      P4_NOTIFICATION_FAILED.set(true);
5584	    } catch (InterruptedException interrupted) {
5585	      Thread.currentThread().interrupt();
5586	      P4_NOTIFICATION_FAILED.set(true);
5587	    }
5588	  }
