package com.citi.put.checks.studio.guided.session;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.function.Supplier;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;

/** All session mutations serialize on one PostgreSQL row; idempotency is in the same commit. */
public final class GuidedSessionRepository {
  private final JdbcTemplate jdbc;
  private final TransactionTemplate transactions;
  private final GuidedContracts contracts;

  public GuidedSessionRepository(
      JdbcTemplate jdbc, TransactionTemplate transactions, GuidedContracts contracts) {
    this.jdbc = jdbc;
    this.transactions = transactions;
    this.contracts = contracts;
  }

  public <T> T transaction(Supplier<T> operation) {
    return transactions.execute(s -> operation.get());
  }

  public record Session(ObjectNode document, ObjectNode progress) {}

  public Session lock(String id) {
    var rows =
        jdbc.query(
            "SELECT document::text,progress::text FROM studio_guided_sessions WHERE "
                + "session_id=? FOR UPDATE",
            (rs, n) ->
                new Session(
                    (ObjectNode) contracts.parse(rs.getString(1)),
                    (ObjectNode) contracts.parse(rs.getString(2))),
            id);
    if (rows.isEmpty()) {
      throw new GuidedSessionException("FORBIDDEN_SCOPE", 403);
    }
    return rows.getFirst();
  }

  public void insert(ObjectNode doc) {
    jdbc.update(
        "INSERT INTO studio_guided_sessions"
            + "(session_id,test_id,principal_id,scope_hash,state,expires_at,document)"
            + " VALUES (?,?,?,?,?,?,?::jsonb)",
        doc.path("sessionId").asText(),
        doc.path("testId").asText(),
        doc.path("scope").path("principalId").asText(),
        doc.path("scopeHash").asText(),
        doc.path("state").asText(),
        Timestamp.from(Instant.parse(doc.path("expiresAt").asText())),
        doc.toString());
  }

  public void save(Session session) {
    contracts.validate("session", session.document());
    jdbc.update(
        "UPDATE studio_guided_sessions SET state=?,document=?::jsonb,progress=?::jsonb "
            + "WHERE session_id=?",
        session.document().path("state").asText(),
        session.document().toString(),
        session.progress().toString(),
        session.document().path("sessionId").asText());
  }

  public void namespaceLock(String namespace) {
    jdbc.queryForObject(
        "SELECT pg_advisory_xact_lock(hashtextextended(?,0))", Object.class, namespace);
  }

  public JsonNode duplicate(String namespace, String route, String key, String digest) {
    var found =
        jdbc.query(
            "SELECT request_digest,response::text FROM studio_guided_commands"
                + " WHERE namespace=? AND route=? AND idempotency_key=?",
            (rs, n) -> {
              GuidedSessionException.require(
                  rs.getString(1).equals(digest), "IDEMPOTENCY_CONFLICT", 409);
              return contracts.parse(rs.getString(2));
            },
            namespace,
            route,
            key);
    return found.isEmpty() ? null : found.getFirst();
  }

  public void command(
      String namespace, String route, String key, String digest, JsonNode response) {
    jdbc.update(
        "INSERT INTO studio_guided_commands VALUES (?,?,?,?,?::jsonb)",
        namespace,
        route,
        key,
        digest,
        response.toString());
  }

  public void insertAction(ObjectNode action, JsonNode proposal) {
    contracts.validate("action", proposal);
    GuidedSessionException.require(
        GuidedContracts.hash(proposal).equals(action.path("requestDigest").asText()),
        "INVALID_CONTRACT",
        422);
    contracts.validate("ledger", action);
    jdbc.update(
        "INSERT INTO studio_guided_actions "
            + "(admission_id,session_id,step_id,ordinal,document,proposal) VALUES "
            + "(?,?,?,?,?::jsonb,?::jsonb)",
        action.path("admission").path("admissionId").asText(),
        action.path("sessionId").asText(),
        action.path("coordinate").path("stepId").asText(),
        action.path("coordinate").path("ordinal").asInt(),
        action.toString(),
        proposal.toString());
  }

  public List<ObjectNode> actions(String sessionId) {
    return jdbc.query(
        "SELECT document::text FROM studio_guided_actions WHERE session_id=? ORDER BY "
            + "step_id,ordinal",
        (rs, n) -> (ObjectNode) contracts.parse(rs.getString(1)),
        sessionId);
  }

  public JsonNode proposal(String admission) {
    return contracts.parse(
        jdbc.queryForObject(
            "SELECT proposal::text FROM studio_guided_actions WHERE admission_id=?",
            String.class,
            admission));
  }

  public void saveAction(ObjectNode action) {
    contracts.validate("ledger", action);
    jdbc.update(
        "UPDATE studio_guided_actions SET document=?::jsonb WHERE admission_id=?",
        action.toString(),
        action.path("admission").path("admissionId").asText());
  }

  public List<String> expired(Instant now) {
    return jdbc.queryForList(
        "SELECT session_id FROM studio_guided_sessions WHERE expires_at<=? AND state NOT IN"
            + " ('SUCCEEDED','PUBLICATION_CONFLICT','FAILED','UNKNOWN_OUTCOME','CANCELLED','EXPIRED')",
        String.class,
        Timestamp.from(now));
  }

  public void finalizationIdentity(String id, String hash) {
    jdbc.update(
        "UPDATE studio_guided_sessions SET finalization_identity=? WHERE session_id=?", hash, id);
  }

  public void evidence(String id, String scope, String evidenceId, String ref) {
    jdbc.update(
        "INSERT INTO studio_guided_evidence VALUES (?,?,?,'guided',?)", id, evidenceId, scope, ref);
  }
}
package com.citi.put.checks.studio.guided.session;

import com.citi.put.checks.security.CsiOwnershipEvaluator;
import java.time.Clock;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@Configuration
@EnableConfigurationProperties(GuidedSessionProperties.class)
public class GuidedSessionConfiguration {
  @Bean
  GuidedContracts guidedContracts() {
    return new GuidedContracts();
  }

  @Bean
  GuidedSessionRepository guidedSessionRepository(
      JdbcTemplate jdbc, PlatformTransactionManager manager, GuidedContracts contracts) {
    return new GuidedSessionRepository(jdbc, new TransactionTemplate(manager), contracts);
  }

  @Bean
  GuidedSessionService guidedSessionService(
      GuidedSessionRepository repository,
      GuidedContracts contracts,
      GuidedSessionAccess access,
      GuidedSessionProperties properties,
      JdbcTemplate jdbc,
      com.citi.put.checks.studio.guided.translation.GuidedTranslationStore translation,
      com.citi.put.checks.studio.guided.translation.GuidedClarificationContextStore questions,
      com.citi.put.checks.studio.secrets.SecretRevocationSweep revocation,
      com.citi.put.checks.studio.secrets.SecretAuditLifecycle audit,
      com.citi.put.checks.studio.StudioExecutionProperties execution) {
    var service =
        new GuidedSessionService(repository, contracts, access, properties, Clock.systemUTC());
    var materialization =
        new com.citi.put.checks.studio.guided.bridge.GuidedMaterializationService(jdbc, contracts);
    service.installBridge(
        materialization,
        new com.citi.put.checks.studio.guided.bridge.GuidedPreparationStore(jdbc, contracts),
        new com.citi.put.checks.studio.guided.bridge.GuidedBindingStore(
            jdbc, contracts, materialization),
        new com.citi.put.checks.studio.guided.bridge.GuidedAssignmentStore(jdbc, contracts));
    service.installTranslation(translation, questions);
    service.installSecretRevocation(revocation);
    service.installSecretAudit(audit);
    service.installExecutionEnabled(execution::enabledOrDefault);
    revocation.installGuidedStop(service::secretRevoked);
    return service;
  }

  @Bean
  @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(
      name = "studio.guided-authoring.runner-origin")
  com.citi.put.checks.studio.guided.bridge.GuidedRunnerClient guidedRunnerClient(
      @org.springframework.beans.factory.annotation.Value(
              "${studio.guided-authoring.runner-origin}")
          String origin,
      @org.springframework.beans.factory.annotation.Value(
              "${studio.guided-authoring.controller-token-file}")
          String tokenFile,
      GuidedContracts contracts)
      throws java.security.NoSuchAlgorithmException {
    return new com.citi.put.checks.studio.guided.bridge.GuidedRunnerClient(
        java.net.URI.create(origin),
        javax.net.ssl.SSLContext.getDefault(),
        () -> {
          try {
            return java.nio.file.Files.readString(java.nio.file.Path.of(tokenFile)).strip();
          } catch (java.io.IOException failure) {
            throw new GuidedSessionException("UNAUTHENTICATED", 401);
          }
        },
        contracts);
  }

  @Bean
  @ConditionalOnMissingBean(com.citi.put.checks.studio.guided.bridge.GuidedRunnerClient.class)
  com.citi.put.checks.studio.guided.bridge.GuidedRunnerClient unavailableGuidedRunnerClient(
      GuidedContracts contracts) throws java.security.NoSuchAlgorithmException {
    return new com.citi.put.checks.studio.guided.bridge.GuidedRunnerClient(
        java.net.URI.create("https://unconfigured.invalid"),
        javax.net.ssl.SSLContext.getDefault(),
        () -> {
          throw new GuidedSessionException("RUNTIME_INCOMPATIBLE", 409);
        },
        contracts);
  }

  @Bean
  com.citi.put.checks.studio.guided.bridge.GuidedDispatchService guidedDispatchService(
      GuidedSessionService sessions,
      com.citi.put.checks.studio.guided.bridge.GuidedRunnerClient runner,
      JdbcTemplate jdbc,
      GuidedContracts contracts,
      com.citi.put.checks.studio.dispatch.StudioReferenceResolver references) {
    var dispatch =
        new com.citi.put.checks.studio.guided.bridge.GuidedDispatchService(
            sessions,
            new com.citi.put.checks.studio.guided.bridge.GuidedMaterializationService(
                jdbc, contracts),
            runner);
    dispatch.installReferences(references);
    sessions.installStopSender(dispatch::stop);
    return dispatch;
  }

  @Bean
  @ConditionalOnMissingBean(GuidedSessionAccess.class)
  GuidedSessionAccess guidedProductionAccess(
      com.citi.put.checks.studio.guided.translation.GuidedSourceSnapshotRepository snapshots,
      com.citi.put.checks.studio.guided.translation.GuidedSourceClassifier classifier,
      com.citi.put.checks.studio.guided.translation.GuidedSourceInputResolver resolver,
      com.citi.put.checks.studio.guided.translation.GuidedTranslationStore store,
      com.citi.put.checks.studio.guided.translation.GuidedStepVerifier verifier,
      CsiOwnershipEvaluator ownership,
      com.citi.put.checks.studio.guided.publication.ObservedReplayPins pins,
      com.citi.put.checks.studio.dispatch.StudioReferenceResolver references,
      com.citi.put.checks.studio.secrets.StudioSecretUseAuthorization secretUse) {
    return new com.citi.put.checks.studio.guided.translation.GuidedProductionSessionAccess(
        snapshots, classifier, resolver, store, verifier, ownership, pins, references, secretUse);
  }
}
package com.citi.put.checks.studio.guided.translation;

import com.fasterxml.jackson.databind.JsonNode;

/** Trusted structural failure annotation, with no page text heuristic or password value read. */
public final class LoginRequiredSignature {
  private LoginRequiredSignature() {}

  public static boolean matches(JsonNode observation) {
    if (observation.path("coverage").path("passwordControls").asInt() < 1) {
      return false;
    }
    for (JsonNode node : observation.path("nodes")) {
      if (node.path("visible").asBoolean()
          && node.path("actionable").asBoolean()
          && (java.util.Set.of("button", "input").contains(node.path("elementType").asText())
              || node.path("role").asText().equals("button"))) {
        return true;
      }
    }
    return false;
  }
}
